import{d as c,C as t,o as g,c as m,j as a,a as s,E as n,a3 as b}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"道德经第二十二章","description":"从曲全、少得到抱一与四个不自，理解不争如何保全。","frontmatter":{"title":"道德经第二十二章","description":"从曲全、少得到抱一与四个不自，理解不争如何保全。","category":"guide","aliases":["道德经第二十二章","老子第二十二章","dao de jing chapter 22"],"source":["王弼《道德真经注》卷二"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-22.md","filePath":"daoism/dao-de-jing/chapter-22.md","lastUpdated":1794189804000}'),p={name:"daoism/dao-de-jing/chapter-22.md"},_=c({...p,setup(u){const r=[{id:"six-reversals",label:"曲则全，枉则直",showLabel:!0,sentences:[[{text:"曲",glossary:"qu"},"则全，",{text:"枉",glossary:"wang"},"则直，",{text:"洼",glossary:"wa"},"则盈，",{text:"弊",glossary:"bi"},"则新，少则得，多则惑。"]],note:["【白话】能委曲便得保全，受屈便能伸直，低洼处便得充盈，敝旧便能更新；少取而能得，多求反受迷惑。这六组相反相成的说法，转变了只重伸张、盈满、求多的眼光。","【王弼注择要】少得、多惑，注以树为喻，说「转多转远其根，转少转得其本」。王弼关注逐末而远本，与减少纷逐而得本的差别。","【读法】曲、枉不是给一切伤害作合理化；这些反转需连后文不自与不争看。弊在此取敝旧义，保留本站字形，与第十五章蔽字分开。"]},{id:"holding-one-as-a-model",label:"是以圣人抱一为天下式",showLabel:!0,sentences:[["是以圣人",{text:"抱一",glossary:"baoyi"},"为天下",{text:"式",glossary:"shi"},"。"]],note:["【白话】因此圣人守住根本、持一不散，作为天下的法式。这里从少则得接来，强调不被众多枝末分散。","【王弼注择要】「一，少之极也。式，犹则之也。」注以少之极说明一，以准则说明式，将前文的得本与圣人行事相连。","【读法】本章抱一循少之极、得本来读；与第十章抱一清神相关，却不把两处合成一套固定修炼技术。为天下式也不是处处强加同一形式。"]},{id:"four-ways-of-not-asserting-self",label:"不自见，故明",showLabel:!0,sentences:[["不自",{text:"见",glossary:"xian"},"，故明；不",{text:"自是",glossary:"zishi"},"，故",{text:"彰",glossary:"zhang"},"；不",{text:"自伐",glossary:"zifa"},"，故有功；不",{text:"自矜",glossary:"zijin"},"，故",{text:"长",glossary:"chang"},"。"]],note:["【白话】不自我显露，反能明；不自以为是，是非反能彰显；不自夸功劳，功反能成立；不自高自大，德反能增长。","【王弼注择要】注在前面曲、枉、洼、弊下分别连到四个不自，其中说「不自矜则其德长也」。这里的长，本页据此取德增长义。","【读法】见读 xiàn，取显示义；长本页循德长读 zhǎng，也有从长久、为长解释的读法。四句并非不准表达观点、记录成果，而是不以自我标举代替事情本身。"]},{id:"non-contention-and-wholeness",label:"夫唯不争，故天下莫能与之争",showLabel:!0,sentences:[["夫唯",{text:"不争",glossary:"buzheng"},"，故天下莫能与之争。"],["古之所谓“曲则全”者，岂虚言哉！",{text:"诚",glossary:"cheng"},"全而归之。"]],note:["【白话】正因为不以争胜自立，天下便没有谁能在这一路数上与他相争。古人所说的曲则全，难道是空话吗！确实能得到保全而归于它。","【王弼注择要】本章所引录文末尾同样以曲则全、诚全而归之收束；该处未另附长注。结合前文王弼的得本解释，本页将它读作对整章保全之旨的回扣。","【读法】末句归之的指向可有不同理解，本页暂以归于保全来读。莫能与之争是章中对不争的推论，不能当作现实中永不受损的保证。"]}],o=[{id:"qu",term:"曲",sense:1},{id:"wang",term:"枉",sense:1},{id:"wa",term:"洼",sense:1},{id:"ying",term:"盈",sense:1},{id:"bi",term:"弊",sense:1},{id:"baoyi",term:"抱一",sense:2},{id:"shi",term:"式",sense:1},{id:"xian",term:"见",sense:1,pinyin:"xiàn"},{id:"zishi",term:"自是",sense:1},{id:"zhang",term:"彰",sense:1},{id:"zifa",term:"自伐",sense:1},{id:"zijin",term:"自矜",sense:1},{id:"chang",term:"长",sense:2,pinyin:"zhǎng"},{id:"buzheng",term:"不争",sense:1},{id:"cheng",term:"诚",sense:1}];return(x,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return g(),m("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第二十二章",tabindex:"-1"},[s("道德经第二十二章 "),a("a",{class:"header-anchor",href:"#道德经第二十二章","aria-label":'Permalink to "道德经第二十二章"'},"​")],-1)),n(i,{title:"曲与全之间，先看怎样放下自我标举",summary:"本章用六组反转起笔，接到抱一为式，再把不自见、不自是、不自伐、不自矜写成具体行事方式，最后回到曲则全。",points:[{label:"先读",text:"六组则句相互映照，不把任何一句抽成无条件的成败定律。"},{label:"再辨",text:"少得、多惑与抱一相接，重心是根本与纷逐的关系。"},{label:"后看",text:"四个不自说明不争的实际内容，再回看诚全而归之。"}],hint:"可与第二十四章对照读：本章从不自说所得，后章从自说所失。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[s("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),n(l,{sections:r,glossary:o}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[s("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),n(d,{lines:[{text:"少则得，多则惑。",tone:"由多返本",guide:"王弼用树的枝末与根本解释，重心在有没有离本，不以数量少本身为美。"},{text:"不自见，故明；不自是，故彰。",tone:"明与自我显露",guide:"明与彰不靠先肯定自己来取得；保持判断空间，才有可能看见事情本身。"},{text:"夫唯不争，故天下莫能与之争。",tone:"不争的推论",guide:"连四个不自理解，不把它变成退让后必定胜出的策略承诺。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[s("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),n(h,{items:o}),e[4]||(e[4]=b('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-六组反转与四个不自有什么关系" tabindex="-1">象：六组反转与四个不自有什么关系？ <a class="header-anchor" href="#象-六组反转与四个不自有什么关系" aria-label="Permalink to &quot;象：六组反转与四个不自有什么关系？&quot;">​</a></h3><p>六组则句先改变对曲直、盈亏与多少的直觉，四个不自再给出行为上的对应。王弼逐句相连，使曲则全不只是一条抽象格言，而是对自我显耀如何妨碍保全的反省。</p><h3 id="理-抱一为什么跟在少则得之后" tabindex="-1">理：抱一为什么跟在少则得之后？ <a class="header-anchor" href="#理-抱一为什么跟在少则得之后" aria-label="Permalink to &quot;理：抱一为什么跟在少则得之后？&quot;">​</a></h3><p>注以一为少之极，并以前面的树喻说明得本。这里所少的是使人离本的纷逐，所一是根本的持守；不能据此断言任务越少越好，或任何复杂性都应删除。</p><h3 id="用-不争与维护必要权益能否并行" tabindex="-1">用：不争与维护必要权益能否并行？ <a class="header-anchor" href="#用-不争与维护必要权益能否并行" aria-label="Permalink to &quot;用：不争与维护必要权益能否并行？&quot;">​</a></h3><p>可以陈述事实、提出诉求、约定责任，同时减少面子争胜和功劳独占。若持续受到伤害，保全也包括止损、求助与明确边界；不必用曲则全要求自己或他人无限忍让。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>先辨根本，再做减法。</strong> 面对很多目标，先确认真正需要完成的事与相互依赖，再减少为显得能干而增加的动作。少则得可以启发这种检查，不能替代具体分析。</p><p><strong>让功与判断回到事实。</strong> 复盘时如实记录自己的工作，也承认协作与条件；讨论时给出理由，也允许纠正。减少自夸、自是，未必需要减少清楚表达。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：最近一次坚持己见，是因为事实充分，还是因为不愿撤回自己的话？什么才是这件事需要保全的根本？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>本站保留「弊则新」，所据 HFL 录文亦作「弊」；此处按敝旧义读，不与第十五章「蔽不新成」混同。</li><li>「抱一」按王弼「一，少之极也」另设义项；长循「其德长也」暂读 zhǎng、取增长义，其他取法并不据此取消。</li><li>「诚全而归之」保留原句，其归之指向不作唯一裁定；最后一段不伪造该处未见的王弼专注。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_002.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷二 HFL 本电子录文，001b–002a</a>。</p>',15))])}}});export{y as __pageData,_ as default};
